<?php
declare(strict_types=1);

/**
 * install_mrl_team_redesign.php
 *
 * VERSION: v009
 * LAST MODIFIED: 8/27/2026 7:36:25 pm
 *
 * PURPOSE:
 * Controlled consolidation/cleanup of the verified working team_redesign.php v008.
 *
 * EXPECTED INPUT:
 * - exact team_redesign.php v008 installed by the corrected v008 installer
 * - exact mrl_team/admin_team_page_content.php v003
 * - valid four-panel mrl_team/mrl_team_page_content.json
 *
 * OUTPUT:
 * - complete team_redesign.php VERSION: v009
 *
 * SAFETY:
 * - exact SHA-256 baseline checks before any write
 * - backs up team_redesign.php before replacement
 * - does not write JSON, Content Manager, theme helper, profile redesign,
 *   production team.php, or production profile.php
 * - verifies production hashes after installation
 * - verifies critical pick/chart/theme/menu signatures after installation
 *
 * CHANGELOG:
 *
 * v009 (8/27/2026 7:36:25 pm)
 * - CLEANUP: Consolidates layered v001-v008 redesign CSS into one current stylesheet.
 * - CLEANUP: Removes confirmed-unused legacy helper functions and stale selectors.
 * - CLEANUP: Removes unused pick-window timestamp variable.
 * - PRESERVE: Current behavior and data paths.
 */

date_default_timezone_set('America/New_York');

const EXPECTED_TEAM_SHA256 = '28d01f71a74d39081150f1dab0a34ce3003f4b01cde58ed717f8ed96c4d1cf4d';
const EXPECTED_MANAGER_SHA256 = 'fe2a8c9050f6b5c6055975b3f211dd3ca0b57363ff5c6b225d74cf5a02bf4bbb';

$base=__DIR__;
$team=$base.'/team_redesign.php';
$manager=$base.'/mrl_team/admin_team_page_content.php';
$json=$base.'/mrl_team/mrl_team_page_content.json';
$helper=$base.'/mrl_team/mrl_theme_helper.php';
$profileRedesign=$base.'/profile_redesign.php';
$prodTeam=$base.'/team.php';
$prodProfile=$base.'/profile.php';

function ih(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
function sr(string $label,bool $ok,string $detail=''):void{echo '<tr><td>'.ih($label).'</td><td class="'.($ok?'ok':'bad').'">'.($ok?'PASS':'FAIL').'</td><td>'.ih($detail).'</td></tr>';}
function aw(string $path,string $data):bool{$tmp=$path.'.tmp_'.bin2hex(random_bytes(4));if(file_put_contents($tmp,$data,LOCK_EX)===false)return false;if(!@rename($tmp,$path)){@unlink($tmp);return false;}return true;}

$replacement=base64_decode('',true);
$replacementOk=is_string($replacement)
    && strpos($replacement,'VERSION: v009')!==false
    && strpos($replacement,'team_redesign.php v009 - consolidated current presentation')!==false
    && strpos($replacement,'teampage_user_has_rd_for_segment')===false
    && strpos($replacement,'teampage_user_has_active_segment_pick')===false;

$teamExists=is_file($team);
$managerExists=is_file($manager);
$jsonExists=is_file($json);
$helperExists=is_file($helper);
$profileRedesignExists=is_file($profileRedesign);
$prodTeamExists=is_file($prodTeam);
$prodProfileExists=is_file($prodProfile);

$teamHash=$teamExists?hash_file('sha256',$team):'';
$managerHash=$managerExists?hash_file('sha256',$manager):'';
$teamBaselineOk=$teamExists && $teamHash===EXPECTED_TEAM_SHA256 && strpos((string)file_get_contents($team),'VERSION: v008')!==false;
$managerBaselineOk=$managerExists && $managerHash===EXPECTED_MANAGER_SHA256 && strpos((string)file_get_contents($manager),'VERSION: v003')!==false;

$jsonOk=false;$panelCounts=[];
if($jsonExists){
    $raw=file_get_contents($json);
    $data=is_string($raw)?json_decode($raw,true):null;
    if(is_array($data)){
        $jsonOk=true;
        foreach(['admin_league_panel','admin_hosting_panel','league_panel','team_panel'] as $key){
            $items=$data[$key]['items']??null;
            $panelCounts[$key]=is_array($items)?count($items):-1;
            if($panelCounts[$key]<0)$jsonOk=false;
        }
    }
}

$helperVersionOk=$helperExists && strpos((string)file_get_contents($helper),'VERSION: v002')!==false;
$profileVersionOk=$profileRedesignExists && strpos((string)file_get_contents($profileRedesign),'VERSION: v002')!==false;

$prodTeamBefore=$prodTeamExists?hash_file('sha256',$prodTeam):'';
$prodProfileBefore=$prodProfileExists?hash_file('sha256',$prodProfile):'';
$jsonBefore=$jsonExists?hash_file('sha256',$json):'';
$managerBefore=$managerExists?hash_file('sha256',$manager):'';
$helperBefore=$helperExists?hash_file('sha256',$helper):'';
$profileRedesignBefore=$profileRedesignExists?hash_file('sha256',$profileRedesign):'';

$apply=isset($_POST['apply'])&&$_POST['apply']==='1';
$msgs=[];$success=false;

if($apply&&$replacementOk&&$teamBaselineOk&&$managerBaselineOk&&$jsonOk&&$helperVersionOk&&$profileVersionOk&&$prodTeamExists&&$prodProfileExists){
    $backupDir=$base.'/_migration_backups/team_redesign_v009_'.date('Ymd_His');
    $ok=(is_dir($backupDir)||mkdir($backupDir,0755,true));
    if(!$ok){$msgs[]='Could not create backup directory.';}
    elseif(!copy($team,$backupDir.'/team_redesign.php')){$ok=false;$msgs[]='Could not back up team_redesign.php.';}
    else{$msgs[]='Backed up exact working v008 team_redesign.php.';}

    if($ok&&!aw($team,$replacement)){$ok=false;$msgs[]='Could not install team_redesign.php v009.';}
    elseif($ok){$msgs[]='Installed consolidated team_redesign.php v009.';}

    if($ok){
        $installed=(string)file_get_contents($team);
        $checks=[
            'v009 header'=>strpos($installed,'VERSION: v009')!==false,
            'four-panel JSON loader'=>strpos($installed,'foreach ($teamPageContentPanelKeys as $panelKey)')!==false,
            'Cars theme'=>strpos($installed,'mrl-theme-cars')!==false,
            'Starry Night theme'=>strpos($installed,'mrl-theme-starry-night')!==false,
            'Dark theme'=>strpos($installed,'mrl-theme-dark')!==false,
            'Light theme'=>strpos($installed,'mrl-theme-light')!==false,
            'normal form route'=>strpos($installed,'include $currentForm;')!==false,
            'LP route'=>strpos($installed,"include 'team-late-pick.php';")!==false,
            'RP/RD route'=>strpos($installed,"include 'team_replacement_driver.php';")!==false,
            'current chart'=>strpos($installed,"include 'current_segment_chart.php';")!==false,
            'prior-year charts'=>strpos($installed,"include 'prior_year_user_team_chart.php';")!==false,
            'unused RD helper removed'=>strpos($installed,'teampage_user_has_rd_for_segment')===false,
            'unused active-pick helper removed'=>strpos($installed,'teampage_user_has_active_segment_pick')===false,
            'unused timestamp removed'=>strpos($installed,'$pickWindowOpenTs')===false,
        ];
        foreach($checks as $label=>$pass){
            $msgs[]=($pass?'PASS: ':'FAIL: ').$label;
            if(!$pass)$ok=false;
        }
    }

    $prodTeamUntouched=$prodTeamBefore!==''&&$prodTeamBefore===hash_file('sha256',$prodTeam);
    $prodProfileUntouched=$prodProfileBefore!==''&&$prodProfileBefore===hash_file('sha256',$prodProfile);
    $jsonUntouched=$jsonBefore!==''&&$jsonBefore===hash_file('sha256',$json);
    $managerUntouched=$managerBefore!==''&&$managerBefore===hash_file('sha256',$manager);
    $helperUntouched=$helperBefore!==''&&$helperBefore===hash_file('sha256',$helper);
    $profileRedesignUntouched=$profileRedesignBefore!==''&&$profileRedesignBefore===hash_file('sha256',$profileRedesign);

    foreach([
        'production team.php unchanged'=>$prodTeamUntouched,
        'production profile.php unchanged'=>$prodProfileUntouched,
        'menu JSON unchanged'=>$jsonUntouched,
        'Content Manager v003 unchanged'=>$managerUntouched,
        'theme helper unchanged'=>$helperUntouched,
        'profile_redesign.php unchanged'=>$profileRedesignUntouched,
    ] as $label=>$pass){
        $msgs[]=($pass?'Verified ':'ERROR: ').$label.'.';
        if(!$pass)$ok=false;
    }

    $success=$ok;
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><title>MRL Team Redesign Cleanup Installer v009</title>
<style>*{box-sizing:border-box}html{background:#111}body{margin:0;color:#eee;font-family:Tahoma,Verdana,Segoe UI,sans-serif}.wrap{width:94%;max-width:1200px;margin:20px auto}.card{background:#202020;border:1px solid #555;border-radius:14px;padding:20px;margin-bottom:16px}h1,h2{color:#efc982}table{width:100%;border-collapse:collapse}td{padding:9px;border-bottom:1px solid #444;vertical-align:top}.ok{color:#61e493}.bad{color:#ff7777}button{padding:11px 20px;background:#1466c9;color:#fff;border:1px solid #5a7fb5;border-radius:9px;font-weight:800;cursor:pointer}a,code{color:#76cfff}li{line-height:1.45;margin-bottom:5px}</style></head>
<body><div class="wrap">
<div class="card"><h1>MRL Team Redesign Cleanup Installer v009</h1><p>This is the consolidation pass: same working behavior, substantially less accumulated redesign-era presentation code.</p></div>
