<?php sr('Exact working team_redesign.php v008 baseline',$teamBaselineOk,$teamHash); ?>
<?php sr('Exact Content Manager v003 baseline',$managerBaselineOk,$managerHash); ?>
<?php sr('Four-panel menu JSON readable',$jsonOk,$json); ?>
<?php foreach($panelCounts as $k=>$c): ?><?php sr('JSON '.$k,$c>=0,(string)$c.' item(s)'); ?><?php endforeach; ?>
<?php sr('Theme helper v002 present',$helperVersionOk,$helper); ?>
<?php sr('Profile redesign v002 present',$profileVersionOk,$profileRedesign); ?>
<?php sr('Complete v009 replacement embedded',$replacementOk,'Exact full-file replacement.'); ?>
<?php sr('Production team.php present',$prodTeamExists,$prodTeam); ?>
<?php sr('Production profile.php present',$prodProfileExists,$prodProfile); ?>
</table></div>
<?php if($replacementOk&&$teamBaselineOk&&$managerBaselineOk&&$jsonOk&&$helperVersionOk&&$profileVersionOk&&$prodTeamExists&&$prodProfileExists): ?>
<div class="card"><h2>Cleanup scope</h2><ul>
<li>Consolidates the accumulated redesign CSS blocks into one current stylesheet.</li>
<li>Removes two helper functions confirmed to have no call sites.</li>
<li>Removes an unused pick-window timestamp variable.</li>
